CREATE TABLE bootstrap_authorizations(authorization_id TEXT PRIMARY KEY NOT NULL, document BLOB NOT NULL, sha256 TEXT NOT NULL, operator_sid TEXT NOT NULL, approved_at TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('READY','ACTIVE','FINISHED','STOPPED','REVOKED')), host_epoch TEXT, used_cycles INTEGER NOT NULL DEFAULT 0 CHECK(used_cycles BETWEEN 0 AND 20), stop_reason TEXT) STRICT;
CREATE TABLE bootstrap_cycles(operation_id TEXT PRIMARY KEY NOT NULL REFERENCES operations(operation_id), authorization_id TEXT NOT NULL REFERENCES bootstrap_authorizations(authorization_id), cycle INTEGER NOT NULL CHECK(cycle BETWEEN 1 AND 20), host_epoch TEXT NOT NULL, worker_epoch TEXT NOT NULL, worker_pid INTEGER NOT NULL, worker_start_ticks INTEGER NOT NULL, reserved_at TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'RESERVED', telemetry BLOB, terminal_report BLOB, UNIQUE(authorization_id,cycle)) STRICT;
CREATE TRIGGER bootstrap_authorization_no_delete BEFORE DELETE ON bootstrap_authorizations BEGIN SELECT RAISE(ABORT,'retained bootstrap authorization'); END;
CREATE TRIGGER bootstrap_document_immutable BEFORE UPDATE OF authorization_id,document,sha256,operator_sid,approved_at ON bootstrap_authorizations BEGIN SELECT RAISE(ABORT,'immutable bootstrap document'); END;
CREATE TRIGGER bootstrap_budget_monotonic BEFORE UPDATE OF used_cycles ON bootstrap_authorizations WHEN NEW.used_cycles < OLD.used_cycles BEGIN SELECT RAISE(ABORT,'consumed bootstrap budget'); END;
CREATE TRIGGER bootstrap_cycle_no_delete BEFORE DELETE ON bootstrap_cycles BEGIN SELECT RAISE(ABORT,'retained bootstrap cycle'); END;
CREATE TRIGGER bootstrap_cycle_binding_immutable BEFORE UPDATE OF operation_id,authorization_id,cycle,host_epoch,worker_epoch,worker_pid,worker_start_ticks,reserved_at ON bootstrap_cycles BEGIN SELECT RAISE(ABORT,'immutable bootstrap binding'); END;
CREATE TABLE bootstrap_release(authorization_id TEXT PRIMARY KEY NOT NULL REFERENCES bootstrap_authorizations(authorization_id), recorded_at TEXT NOT NULL, confirmed INTEGER NOT NULL CHECK(confirmed IN (0,1))) STRICT;
ALTER TABLE bootstrap_cycles ADD COLUMN initial_telemetry BLOB;
CREATE TRIGGER bootstrap_release_no_update BEFORE UPDATE ON bootstrap_release BEGIN SELECT RAISE(ABORT,'immutable bootstrap release'); END;
CREATE TRIGGER bootstrap_release_no_delete BEFORE DELETE ON bootstrap_release BEGIN SELECT RAISE(ABORT,'retained bootstrap release'); END;
